mapper.sql:
WHERE delivery_schedules.is_active = 1 AND delivery_schedules.is_close = 0

    AND delivery_schedules.title LIKE CONCAT('%', #{filter.searchText}, '%')


    AND delivery_schedules.created_by = #{userId}


    AND (
    (
    DATE(delivery_schedules.start_date) >= #{filter.dateFrom} AND DATE(delivery_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(delivery_schedules.start_date) <= #{filter.dateTo} AND DATE(delivery_schedules.end_date) >= #{filter.dateTo}
    ) OR (
    DATE(delivery_schedules.start_date) <= #{filter.dateFrom} AND DATE(delivery_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(delivery_schedules.start_date) <= #{filter.dateTo} AND DATE(delivery_schedules.end_date) <= #{filter.dateTo}
    ) OR (
    DATE(delivery_schedules.start_date) >= #{filter.dateFrom} AND DATE(delivery_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(delivery_schedules.start_date) <= #{filter.dateTo} AND DATE(delivery_schedules.end_date) <= #{filter.dateTo}
    ) OR (
    DATE(delivery_schedules.start_date) <= #{filter.dateFrom} AND DATE(delivery_schedules.end_date) >= #{filter.dateFrom} AND
    DATE(delivery_schedules.start_date) <= #{filter.dateTo} AND DATE(delivery_schedules.end_date) >= #{filter.dateTo}
    )
    )

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        delivery_schedules.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

